        stringstream ss(input);
        string line;
        while (getline(ss, line)) {
            int d = 0;
            while (line[d] == '\t') d++;
            string name = line.substr(d);
            int cur = (d > 0 ? depthLen[d - 1] + 1 : 0) + name.size();
            if (name.find('.') != string::npos) ans = max(ans, cur);
            else depthLen[d] = cur;
        }
        return ans;
    }
};

