class Solution:
    def lengthLongestPath(self, input: str) -> int:
        lines = []
        for line in input.split('\n'):
            d = len(line) - len(line.lstrip('\t'))
            lines.append((d, line[d:]))
        self.i = 0

        def dfs(d, prefix):
            if self.i >= len(lines) or lines[self.i][0] != d:
                return 0
            _, name = lines[self.i]
            self.i += 1
            cur = prefix + (1 if prefix else 0) + len(name)
            if '.' in name:
                return cur
            best = 0
            while self.i < len(lines) and lines[self.i][0] == d + 1:
                best = max(best, dfs(d + 1, cur))
            return best

        return dfs(0, 0)

