class Solution {
    vector<pair<int,string>> lines;
    int i = 0;
    int dfs(int d, int prefix) {
        if (i >= (int)lines.size() || lines[i].first != d) return 0;
        auto [_, name] = lines[i++];
        int cur = prefix + (prefix ? 1 : 0) + name.size();
        if (name.find('.') != string::npos) return cur;
        int best = 0;
        while (i < (int)lines.size() && lines[i].first == d + 1)
            best = max(best, dfs(d + 1, cur));
        return best;
    }
