class Solution {
    private List<int[]> meta = new ArrayList<>();
    private List<String> names = new ArrayList<>();
    private int i = 0;

    private int dfs(int d, int prefix) {
        if (i >= names.size() || meta.get(i)[0] != d) return 0;
        String name = names.get(i++);
        int cur = prefix + (prefix > 0 ? 1 : 0) + name.length();
        if (name.indexOf('.') >= 0) return cur;
        int best = 0;
        while (i < names.size() && meta.get(i)[0] == d + 1)
            best = Math.max(best, dfs(d + 1, cur));
        return best;
    }

    public int lengthLongestPath(String input) {
        for (String line : input.split("\n")) {
            int d = 0;
            while (line.charAt(d) == '\t') d++;
            meta.add(new int[]{d});
            names.add(line.substring(d));
        }
        return dfs(0, 0);
    }
}

